function DepositModal({ isOpen, onClose, currentBalance, onDepositSuccess }) {
  if (!isOpen) return null;
  const [amount, setAmount] = _.useState(50);
  const [customAmount, setCustomAmount] = _.useState("");
  const [gateway, setGateway] = _.useState("stripe");
  const [loading, setLoading] = _.useState(false);
  const [error, setError] = _.useState("");
  const [success, setSuccess] = _.useState(null);

  const presets = [10, 25, 50, 100, 250, 500];
  const gateways = [
    { id: "stripe", name: "Credit / Debit Card", sub: "Visa, Mastercard, Apple Pay, Google Pay", icon: "💳", badge: "Instant" },
    { id: "cryptomus", name: "Crypto (Cryptomus / Coinbase)", sub: "USDT TRC20, Bitcoin, Ethereum, Solana", icon: "🪙", badge: "0% Fee" },
    { id: "paypal", name: "PayPal Express Checkout", sub: "PayPal balance, linked cards & bank accounts", icon: "🅿️", badge: "Instant" },
    { id: "upi", name: "Instant UPI / QR Code", sub: "Google Pay, PhonePe, Paytm & NetBanking", icon: "⚡", badge: "Zero Fee" }
  ];

  const finalAmount = customAmount ? Number(customAmount) : amount;

  const handleDeposit = async () => {
    setError("");
    if (!finalAmount || finalAmount < 5) {
      setError("Minimum deposit amount is $5.00");
      return;
    }
    setLoading(true);
    try {
      const hdrs = getAuthHeaders();
      const initRes = await fetch(`${Nd.replace(/\/$/,"")}/api/wallet/deposit/create`, {
        method: "POST",
        headers: hdrs,
        body: JSON.stringify({ amount: finalAmount, gateway })
      });
      const initData = await initRes.json();
      if (!initRes.ok || !initData.success) {
        throw new Error(initData.error || "Deposit initialization failed.");
      }

      // Confirm deposit
      const confRes = await fetch(`${Nd.replace(/\/$/,"")}/api/wallet/deposit/confirm`, {
        method: "POST",
        headers: hdrs,
        body: JSON.stringify({ amount: finalAmount, gateway, transactionId: initData.transactionId })
      });
      const confData = await confRes.json();
      if (!confRes.ok || !confData.success) {
        throw new Error(confData.error || "Deposit confirmation failed.");
      }

      setSuccess({
        transactionId: initData.transactionId,
        amount: finalAmount,
        gateway: initData.gatewayName || gateway,
        newBalance: confData.formattedBalance
      });
      if (onDepositSuccess) {
        onDepositSuccess(confData.formattedBalance);
      }
    } catch (err) {
      setError(err.message || "Failed to process deposit. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return g.jsx("div", {
    className: "fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm",
    onClick: e => { if (e.target === e.currentTarget && !loading) onClose(); },
    children: g.jsxs("div", {
      className: "w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-2xl border border-slate-200",
      children: [
        g.jsxs("div", {
          className: "flex items-center justify-between border-b border-slate-200/80 px-6 py-4 bg-slate-50/50",
          children: [
            g.jsxs("div", {
              className: "flex items-center gap-2.5",
              children: [
                g.jsx("span", { className: "flex h-8 w-8 items-center justify-center rounded-xl bg-indigo-600 text-white text-sm shadow-sm", children: "💳" }),
                g.jsxs("div", {
                  children: [
                    g.jsx("h2", { className: "text-base font-bold text-slate-900", children: "Deposit Funds" }),
                    g.jsx("p", { className: "text-xs text-slate-500", children: "Add balance instantly via secured payment gateway" })
                  ]
                })
              ]
            }),
            g.jsx("button", {
              type: "button",
              onClick: onClose,
              disabled: loading,
              className: "rounded-lg p-1.5 text-slate-400 hover:bg-slate-100 hover:text-slate-700 transition",
              children: "✕"
            })
          ]
        }),

        success ? g.jsxs("div", {
          className: "p-6 text-center space-y-4",
          children: [
            g.jsx("div", { className: "mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 text-2xl", children: "✓" }),
            g.jsxs("div", {
              children: [
                g.jsx("h3", { className: "text-lg font-bold text-slate-900", children: "Deposit Confirmed!" }),
                g.jsxs("p", { className: "text-sm text-slate-600 mt-1", children: ["Successfully credited ", g.jsx("strong", { className: "text-slate-900", children: `${success.amount.toFixed(2)}` }), " to your wallet."] })
              ]
            }),
            g.jsxs("div", {
              className: "rounded-xl bg-slate-50 border border-slate-200 p-4 text-xs space-y-2 text-left",
              children: [
                g.jsxs("div", { className: "flex justify-between", children: [g.jsx("span", { className: "text-slate-500", children: "Transaction Ref" }), g.jsx("span", { className: "font-mono font-medium text-slate-700", children: success.transactionId })] }),
                g.jsxs("div", { className: "flex justify-between", children: [g.jsx("span", { className: "text-slate-500", children: "Payment Gateway" }), g.jsx("span", { className: "font-medium text-slate-700", children: success.gateway })] }),
                g.jsxs("div", { className: "flex justify-between border-t border-slate-200 pt-2 font-semibold text-sm", children: [g.jsx("span", { className: "text-slate-700", children: "New Balance" }), g.jsx("span", { className: "text-emerald-600", children: success.newBalance })] })
              ]
            }),
            g.jsx("button", {
              type: "button",
              onClick: () => { setSuccess(null); onClose(); },
              className: "w-full rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-2.5 shadow-sm transition",
              children: "Done"
            })
          ]
        }) : g.jsxs("div", {
          className: "p-6 space-y-5 max-h-[80vh] overflow-y-auto",
          children: [
            g.jsxs("div", {
              className: "flex items-center justify-between rounded-xl bg-indigo-50/70 border border-indigo-100 p-3.5",
              children: [
                g.jsxs("div", {
                  children: [
                    g.jsx("p", { className: "text-[11px] font-semibold text-indigo-700 uppercase tracking-wider", children: "Current Wallet Balance" }),
                    g.jsx("p", { className: "text-2xl font-extrabold text-slate-900 mt-0.5", children: currentBalance })
                  ]
                }),
                g.jsx("span", { className: "rounded-lg bg-white px-2.5 py-1 text-xs font-semibold text-indigo-700 border border-indigo-200/60 shadow-xs", children: "USD Wallet" })
              ]
            }),

            g.jsxs("div", {
              className: "space-y-2",
              children: [
                g.jsx("label", { className: "block text-xs font-bold text-slate-700 uppercase tracking-wider", children: "Select Deposit Amount" }),
                g.jsx("div", {
                  className: "grid grid-cols-3 sm:grid-cols-6 gap-2",
                  children: presets.map(p => {
                    const isSelected = !customAmount && amount === p;
                    return g.jsxs("button", {
                      key: p,
                      type: "button",
                      onClick: () => { setAmount(p); setCustomAmount(""); },
                      className: fo("rounded-xl py-2 px-3 text-xs font-bold border transition text-center", isSelected ? "bg-indigo-600 text-white border-indigo-600 shadow-sm" : "bg-white text-slate-700 border-slate-200 hover:bg-slate-50"),
                      children: ["$", p]
                    });
                  })
                }),
                g.jsxs("div", {
                  className: "relative mt-2",
                  children: [
                    g.jsx("span", { className: "absolute left-3.5 top-1/2 -translate-y-1/2 text-sm font-bold text-slate-400", children: "$" }),
                    g.jsx("input", {
                      type: "number",
                      min: "5",
                      max: "10000",
                      step: "1",
                      placeholder: "Or enter custom amount (min $5)",
                      value: customAmount,
                      onChange: ev => setCustomAmount(ev.target.value),
                      className: "w-full rounded-xl border border-slate-200 bg-slate-50/50 pl-8 pr-4 py-2 text-xs font-semibold text-slate-900 placeholder:text-slate-400 focus:bg-white focus:border-indigo-600 focus:outline-none transition"
                    })
                  ]
                })
              ]
            }),

            g.jsxs("div", {
              className: "space-y-2",
              children: [
                g.jsx("label", { className: "block text-xs font-bold text-slate-700 uppercase tracking-wider", children: "Choose Payment Gateway" }),
                g.jsx("div", {
                  className: "space-y-2",
                  children: gateways.map(gw => {
                    const isSelected = gateway === gw.id;
                    return g.jsxs("div", {
                      key: gw.id,
                      onClick: () => setGateway(gw.id),
                      className: fo("flex items-center justify-between rounded-xl border p-3 cursor-pointer transition", isSelected ? "border-indigo-600 bg-indigo-50/40 shadow-xs" : "border-slate-200 hover:bg-slate-50/70"),
                      children: [
                        g.jsxs("div", {
                          className: "flex items-center gap-3",
                          children: [
                            g.jsx("span", { className: "text-xl", children: gw.icon }),
                            g.jsxs("div", {
                              children: [
                                g.jsxs("div", { className: "flex items-center gap-2", children: [g.jsx("span", { className: "text-xs font-bold text-slate-900", children: gw.name }), g.jsx("span", { className: "rounded bg-slate-100 px-1.5 py-0.2 text-[9px] font-semibold text-slate-600", children: gw.badge })] }),
                                g.jsx("p", { className: "text-[11px] text-slate-500", children: gw.sub })
                              ]
                            })
                          ]
                        }),
                        g.jsx("div", {
                          className: fo("flex h-4 w-4 items-center justify-center rounded-full border", isSelected ? "border-indigo-600 bg-indigo-600" : "border-slate-300"),
                          children: isSelected && g.jsx("span", { className: "h-1.5 w-1.5 rounded-full bg-white" })
                        })
                      ]
                    });
                  })
                })
              ]
            }),

            error && g.jsx("div", { className: "rounded-xl bg-red-50 border border-red-200/80 p-3 text-xs text-red-600 font-medium", children: error }),

            g.jsxs("button", {
              type: "button",
              disabled: loading || finalAmount < 5,
              onClick: handleDeposit,
              className: "flex w-full items-center justify-center gap-2 rounded-xl bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 py-3 text-sm font-bold text-white shadow-sm transition active:scale-[0.99]",
              children: [
                loading && g.jsx("span", { className: "animate-spin text-sm", children: "⏳" }),
                loading ? "Connecting Gateway..." : `Pay & Deposit ${(finalAmount || 0).toFixed(2)}`
              ]
            }),

            g.jsx("p", {
              className: "text-center text-[10px] text-slate-400",
              children: "🔒 256-Bit SSL Encrypted • Zero Platform Fee • Automated Instant Credit"
            })
          ]
        })
      ]
    })
  });
}

