onExtendOrder:async(I,params=12)=>{
  P(I.id);
  try{
    const hoursNum=typeof params==="object"?Math.max(1,Number(params.hours)||2):(Math.max(1,Number(params)||12));
    const likesNum=typeof params==="object"?Math.max(0,Number(params.likes)||0):0;
    const viewsNum=typeof params==="object"?Math.max(0,Number(params.views)||0):0;
    let newEndTime=null;
    if(I.schedulerOrderId){
      try{
        const resp=await fetch(`${Nd.replace(/\/$/,"")}/api/order/extend/${I.schedulerOrderId}`,{
          method:"POST",
          headers:getAuthHeaders(),
          body:JSON.stringify({
            extensionHours:hoursNum,
            additionalLikes:likesNum,
            additionalViews:viewsNum
          })
        });
        if(resp.ok){
          const resJson=await resp.json();
          newEndTime=resJson.newEndTime;
        }
      }catch(err){console.warn("[Extend API Error]",err);}
    }
    q(prev=>prev.map(o=>{
      if(o.id!==I.id)return o;
      const runs=[...(o.runs||[])];
      const lastRun=runs[runs.length-1];
      const baseTime=lastRun?new Date(lastRun.at).getTime():Date.now();
      const prevDiff=runs.length>=2?(new Date(runs[runs.length-1].at)-new Date(runs[runs.length-2].at)):(45*60*1000);
      const safeInterval=Math.max(15*60*1000,prevDiff||(45*60*1000));
      const count=Math.max(1,Math.round((hoursNum*3600*1000)/safeInterval));
      const avgViews=Math.round(runs.reduce((s,r)=>s+(r.views||0),0)/runs.length)||500;
      const avgLikes=Math.round(runs.reduce((s,r)=>s+(r.likes||0),0)/runs.length)||25;
      const viewsPerRun=viewsNum>0?Math.max(10,Math.round(viewsNum/count)):avgViews;
      const likesPerRun=likesNum>0?Math.max(0,Math.round(likesNum/count)):avgLikes;
      const effectiveAddedLikes=likesNum>0?likesNum:(likesPerRun*count);
      const effectiveAddedViews=viewsNum>0?viewsNum:(viewsPerRun*count);
      const addedRuns=[];
      for(let rIdx=0;rIdx<count;rIdx++){
        addedRuns.push({
          run:runs.length+rIdx+1,
          at:new Date(baseTime+(rIdx+1)*safeInterval).toISOString(),
          views:viewsPerRun,
          likes:likesPerRun,
          shares:0,
          saves:0,
          reposts:0,
          comments:"",
          isAddition:true,
          status:"pending"
        });
      }
      const allRuns=runs.concat(addedRuns);
      const finalEndTime=newEndTime||allRuns[allRuns.length-1].at;
      const additionRecord={
        hours:hoursNum,
        likes:effectiveAddedLikes,
        views:effectiveAddedViews,
        addedAt:new Date().toISOString()
      };
      return{
        ...o,
        runs:allRuns,
        runStatuses:[...(o.runStatuses||[]),...addedRuns.map(()=>"pending")],
        scheduledEndTime:finalEndTime,
        expiryReminderStatus:"extended",
        status:"running",
        addedHours:(o.addedHours||0)+hoursNum,
        addedLikes:(o.addedLikes||0)+effectiveAddedLikes,
        addedViews:(o.addedViews||0)+effectiveAddedViews,
        additions:[...(o.additions||[]),additionRecord],
        lastUpdatedAt:new Date().toISOString()
      };
    }));
    s(`Order extended! Added +${hoursNum}h and +${likesNum>0?likesNum:likesNum===0?"0":likesNum} likes.`);
    setTimeout(()=>re(!0),1000);
  }catch(err){
    console.error("Failed to extend order:",err);
    s("Error extending order: "+err.message);
  }finally{
    P(null);
  }
},
